<?php require_once 'config.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT p.*,u.full_name FROM provider_profiles p JOIN users u ON u.id=p.user_id WHERE p.id=? AND u.status='active'");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('مقدم الخدمة غير موجود.');}$title=$p['title'];$s=$pdo->prepare("SELECT a.* FROM availability a WHERE a.provider_id=? AND a.status='available' AND a.start_time>NOW() AND NOT EXISTS(SELECT 1 FROM appointments ap WHERE ap.availability_id=a.id AND ap.status IN ('pending','confirmed')) ORDER BY a.start_time");$s->execute([$id]);$slots=$s->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){require_login();if(user()['role']!=='customer'){flash('الحجز متاح لحساب الزبون فقط.');go('provider.php?id='.$id);} $aid=(int)($_POST['availability_id']??0);try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM availability WHERE id=? AND provider_id=? AND status='available' AND start_time>NOW() FOR UPDATE");$s->execute([$aid,$id]);$a=$s->fetch();$c=$pdo->prepare("SELECT COUNT(*) FROM appointments WHERE availability_id=? AND status IN ('pending','confirmed')");$c->execute([$aid]);if(!$a||(int)$c->fetchColumn()>0){$pdo->rollBack();flash('هذا الموعد لم يعد متاحاً. اختاري موعداً آخر.');go('provider.php?id='.$id);} $pdo->prepare("INSERT INTO appointments(customer_id,provider_id,availability_id,start_time,end_time,consultation_price,status) VALUES(?,?,?,?,?,?, 'confirmed')")->execute([user()['id'],$id,$aid,$a['start_time'],$a['end_time'],$p['consultation_price']]);$appt=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO payments(appointment_id,amount,payment_method,payment_status) VALUES(?,?,'demo','pending')")->execute([$appt,$p['consultation_price']]);$pdo->commit();flash('تم حجز الموعد. حالة الدفع تجريبية ولم يتم خصم أي مبلغ.');go('my_appointments.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('تعذر إتمام الحجز، حاولي مرة أخرى.');go('provider.php?id='.$id);}}require 'includes/header.php';?><div class="panel"><span class="tag"><?=h($p['specialization'])?></span><h1><?=h($p['title'])?></h1><p>مقدم الخدمة: <?=h($p['full_name'])?></p><p><?=h($p['description'])?></p><p class="price">السعر: <?=number_format($p['consultation_price'],2)?> د.ل</p></div><h2>المواعيد المتاحة</h2><?php if(!user()):?><p>لحجز موعد، <a href="login.php">سجلي الدخول</a> أو <a href="register.php">أنشئي حساباً</a>.</p><?php elseif(user()['role']!=='customer'):?><p>الحجز متاح لحساب الزبون.</p><?php endif;?><div class="grid"><?php foreach($slots as $slot):?><div class="card"><h3><?=h(date('Y-m-d',strtotime($slot['start_time'])))?></h3><p><?=h(date('H:i',strtotime($slot['start_time'])))?> — <?=h(date('H:i',strtotime($slot['end_time'])))?></p><?php if(user()&&user()['role']==='customer'):?><form method="post"><input type="hidden" name="availability_id" value="<?=$slot['id']?>"><button class="btn">احجزي هذا الموعد</button></form><?php endif;?></div><?php endforeach;?><?php if(!$slots):?><div class="card">لا توجد مواعيد مستقبلية متاحة حالياً.</div><?php endif;?></div><?php require 'includes/footer.php';?>
